{% set original_pi = frappe.get_doc("Purchase Invoice", doc.return_against) if doc.return_against else None %}

{% set po_list = [] %}
{% set pr_list = [] %}

{% for d in doc.items %}
  {% if d.purchase_order and d.purchase_order not in po_list %}{% set _ = po_list.append(d.purchase_order) %}{% endif %}
  {% if d.purchase_receipt and d.purchase_receipt not in pr_list %}{% set _ = pr_list.append(d.purchase_receipt) %}{% endif %}
{% endfor %}


{% if original_pi %}
  {% for d in original_pi.items %}
    {% if d.purchase_order and d.purchase_order not in po_list %}{% set _ = po_list.append(d.purchase_order) %}{% endif %}
    {% if d.purchase_receipt and d.purchase_receipt not in pr_list %}{% set _ = pr_list.append(d.purchase_receipt) %}{% endif %}
  {% endfor %}
{% endif %}


{% if not pr_list and po_list %}
  {% set linked_prs = frappe.get_all("Purchase Receipt Item", filters={"purchase_order": ["in", po_list], "docstatus": 1}, fields=["distinct parent"], as_list=True) %}
  {% for pr in linked_prs %}
    {% if pr[0] not in pr_list %}
      {% set _ = pr_list.append(pr[0]) %}
    {% endif %}
  {% endfor %}
{% endif %}

<div class="debit-note-wrapper">
  <style>
    .debit-note-wrapper {
      font-family: Arial, Helvetica, sans-serif;
      font-size: 11px;
      color: #000;
      line-height: 1.35;
      padding: 0 5px;
    }
    .w-100 { width: 100%; border-collapse: collapse; }
    
    /* Top Header */
    .header-table {
      margin-bottom: 12px;
      border-bottom: 2px solid #000;
      padding-bottom: 8px;
    }
    .logo-container {
      text-align: left;
      vertical-align: top;
      padding-bottom: 4px;
    }
    .logo-img {
      max-height: 75px;
      width: auto;
      object-fit: contain;
      display: block;
      margin-left: 0;
      margin-bottom: 8px;
    }
    .company-name {
      font-size: 16px;
      font-weight: bold;
      color: #000;
      margin-top: 2px;
    }
    .doc-title {
      font-size: 24px;
      font-weight: 900;
      letter-spacing: 0.5px;
      color: #000;
      margin-bottom: 4px;
      text-align: right;
    }
    .badge-recipient {
      display: inline-block;
      border: 1px solid #d1d5db;
      background: #f9fafb;
      color: #4b5563;
      font-size: 9.5px;
      font-weight: bold;
      padding: 3px 8px;
      border-radius: 3px;
      letter-spacing: 0.5px;
    }
    .cgst-clause {
      font-size: 8.5px;
      color: #6b7280;
      font-style: italic;
      margin-top: 3px;
      text-align: right;
    }

    /* Cards */
    .card-box {
      border: 1px solid #d1d5db;
      border-radius: 3px;
      background: #fff;
    }
    .card-header {
      background: #f3f4f6;
      font-weight: bold;
      font-size: 9.5px;
      color: #374151;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      padding: 4px 8px;
      border-bottom: 1px solid #d1d5db;
    }
    .card-body {
      padding: 6px 8px;
    }

    /* Reference Banner */
    .ref-banner {
      background: #f9fafb;
      border: 1px solid #d1d5db;
      border-radius: 3px;
      margin: 12px 0 10px 0;
      padding: 8px 10px;
    }

    /* Item Table */
    .items-table {
      width: 100%;
      border-collapse: collapse;
      margin: 10px 0;
    }
    .items-table th {
      background-color: #f3f4f6;
      color: #111827;
      font-size: 9.5px;
      font-weight: bold;
      text-transform: uppercase;
      border: 1px solid #d1d5db;
      padding: 6px 6px;
    }
    .items-table td {
      border: 1px solid #d1d5db;
      padding: 6px 6px;
      vertical-align: top;
      font-size: 10.5px;
    }

    /* Total Table */
    .totals-table {
      width: 100%;
      border: 1px solid #d1d5db;
      border-collapse: collapse;
    }
    .totals-table td {
      padding: 4px 8px;
      border-bottom: 1px solid #e5e7eb;
    }

    /* Helpers */
    .text-center { text-align: center; }
    .text-right { text-align: right; }
    .bold { font-weight: bold; }
    .muted { color: #6b7280; font-size: 9.5px; }
  </style>

  <!-- Header Section -->
  <table class="w-100 header-table">
    <tr>
      <td class="logo-container" style="width: 58%;">
        <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSJw2WH8EpW7r5WFIMyVUkZbb15NRHRrWZ_TVurIT5Ryw&s=10" alt="Logo" class="logo-img">
        <div class="company-name">{{ doc.company }}</div>
        {% if doc.company_gstin %}<div style="font-size: 10.5px;"><b>GSTIN:</b> {{ doc.company_gstin }}</div>{% endif %}
      </td>
      <td style="width: 42%; text-align: right; vertical-align: top;">
        <div class="doc-title">DEBIT NOTE</div>
        <div class="badge-recipient">ORIGINAL FOR RECIPIENT</div>
        <div class="cgst-clause">(Issued u/s 34 of CGST Act, 2017)</div>
      </td>
    </tr>
  </table>

  <!-- Supplier & Metadata Grid -->
  <table class="w-100" style="margin-bottom: 8px;">
    <tr>
      <td style="width: 49%; vertical-align: top; padding-right: 5px;">
        <div class="card-box">
          <div class="card-header">Supplier Details</div>
          <div class="card-body">
            <div class="bold" style="font-size: 11.5px; margin-bottom: 2px;">{{ doc.supplier_name }}</div>
            <div style="color: #374151; font-size: 10px;">{{ doc.address_display or '' }}</div>
            <div style="margin-top: 4px; font-size: 10.5px;">
              {% if doc.supplier_gstin %}<div><b>GSTIN / UIN:</b> {{ doc.supplier_gstin }}</div>{% endif %}
              {% if doc.place_of_supply %}<div><b>Place of Supply:</b> {{ doc.place_of_supply }}</div>{% endif %}
            </div>
          </div>
        </div>
      </td>
      <td style="width: 51%; vertical-align: top; padding-left: 5px;">
        <div class="card-box">
          <div class="card-header">Document Metadata</div>
          <div class="card-body" style="padding: 0;">
            <table class="w-100">
              <tr style="border-bottom: 1px solid #e5e7eb;">
                <td style="padding: 4px 8px; width: 45%;" class="bold">Debit Note No:</td>
                <td style="padding: 4px 8px;" class="text-right bold">{{ doc.name }}</td>
              </tr>
              <tr style="border-bottom: 1px solid #e5e7eb;">
                <td style="padding: 4px 8px;" class="bold">Debit Note Date:</td>
                <td style="padding: 4px 8px;" class="text-right">{{ doc.get_formatted("posting_date") }}</td>
              </tr>
              <tr style="border-bottom: 1px solid #e5e7eb;">
                <td style="padding: 4px 8px;"><b>Supplier Bill No:</b></td>
                <td style="padding: 4px 8px;" class="text-right bold">{{ doc.bill_no or (original_pi.bill_no if original_pi else "N/A") }}</td>
              </tr>
              <tr>
                <td style="padding: 4px 8px;"><b>Supplier Bill Date:</b></td>
                <td style="padding: 4px 8px;" class="text-right">{{ doc.get_formatted("bill_date") or (original_pi.get_formatted("bill_date") if original_pi else "") }}</td>
              </tr>
            </table>
          </div>
        </div>
      </td>
    </tr>
  </table>

  <!-- Items Table -->
  <table class="items-table">
    <thead>
      <tr>
        <th class="text-center" style="width: 4%;">#</th>
        <th style="width: 44%;">Item Description</th>
        <th class="text-center" style="width: 12%;">HSN/SAC</th>
        <th class="text-right" style="width: 10%;">Return Qty</th>
        <th class="text-right" style="width: 14%;">Rate ({{ doc.currency }})</th>
        <th class="text-right" style="width: 16%;">Taxable Amount ({{ doc.currency }})</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td class="text-center">{{ loop.index }}</td>
        <td>
          <div class="bold">{{ item.item_name }}</div>
          {% if item.description and item.description != item.item_name %}
            <div class="muted">{{ item.description }}</div>
          {% endif %}
          {% if item.batch_no %}
            <div class="muted"><b>Batch:</b> {{ item.batch_no }}</div>
          {% endif %}
        </td>
        <td class="text-center">{{ item.gst_hsn_code or item.hsn_sac or '-' }}</td>
        <td class="text-right">{{ (item.qty | abs) }} {{ item.uom }}</td>
        <td class="text-right">{{ item.get_formatted("rate", doc) }}</td>
        <td class="text-right bold">{{ item.get_formatted("amount", doc) | replace("-", "") }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- Calculation & Remarks -->
  <table class="w-100" style="margin-top: 8px;">
    <tr>
      <td style="width: 54%; vertical-align: top; padding-right: 10px;">
        <div class="card-box" style="margin-bottom: 6px;">
          <div class="card-header">Reason / Remarks</div>
          <div class="card-body" style="min-height: 38px; font-size: 10.5px;">
            {{ doc.remarks or "Goods returned / Adjusted against supplier invoice." }}
          </div>
        </div>
        <div style="padding: 2px 4px;">
          <div class="bold" style="font-size: 10px;">Amount in Words:</div>
          <div style="font-style: italic; font-size: 10.5px;">{{ doc.base_in_words or doc.in_words }}</div>
        </div>
      </td>
      <td style="width: 46%; vertical-align: top;">
        <table class="totals-table">
          <tr>
            <td class="bold">Net Taxable Amount:</td>
            <td class="text-right bold">{{ doc.get_formatted("net_total", doc) | replace("-", "") }}</td>
          </tr>
          {% for tax in doc.taxes %}
            {% if tax.tax_amount %}
            <tr>
              <td style="font-size: 10px;">{{ tax.description }}:</td>
              <td style="font-size: 10px;" class="text-right">{{ tax.get_formatted("tax_amount", doc) | replace("-", "") }}</td>
            </tr>
            {% endif %}
          {% endfor %}
          <tr style="background: #f9fafb; font-size: 11px;">
            <td class="bold">Total Debit Amount:</td>
            <td class="text-right bold">{{ doc.get_formatted("grand_total", doc) | replace("-", "") }}</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <!-- Reference & Linked Documents Section -->
  <div class="ref-banner">
    <div style="font-weight: bold; font-size: 9.5px; color: #374151; text-transform: uppercase; margin-bottom: 4px; border-bottom: 1px solid #e5e7eb; padding-bottom: 3px;">
      Reference & Linked Documents
    </div>
    <table class="w-100" style="font-size: 10px;">
      <tr>
        <td style="width: 18%; padding: 2px 0;"><b>Original PI Ref:</b></td>
        <td style="width: 32%; padding: 2px 0;" class="bold">{{ doc.return_against or "Direct Debit Note" }}</td>
        <td style="width: 20%; padding: 2px 0;"><b>Original Inv Date:</b></td>
        <td style="width: 30%; padding: 2px 0;">{{ original_pi.get_formatted("posting_date") if original_pi else "N/A" }}</td>
      </tr>
      <tr>
        <td style="padding: 2px 0;"><b>Original Inv Value:</b></td>
        <td style="padding: 2px 0;">{{ original_pi.get_formatted("grand_total") if original_pi else "N/A" }}</td>
        <td style="padding: 2px 0;"><b>Adjustment Type:</b></td>
        <td style="padding: 2px 0;">Purchase Return / Rate Difference</td>
      </tr>
      <tr>
        <td style="padding: 2px 0;"><b>Purchase Order (PO):</b></td>
        <td style="padding: 2px 0;">{{ po_list | join(', ') if po_list else 'N/A' }}</td>
        <td style="padding: 2px 0;"><b>Purchase Receipt (PR):</b></td>
        <td style="padding: 2px 0;">{{ pr_list | join(', ') if pr_list else 'N/A' }}</td>
      </tr>
    </table>
  </div>

  <!-- Signatures & Declaration -->
  <table class="w-100" style="margin-top: 35px; border-collapse: collapse;">
    <tr>
      <td style="width: 55%; vertical-align: bottom;">
        <div style="font-size: 8.5px; color: #9ca3af; max-width: 300px;">
          Declaration: We declare that this debit note shows the actual quantity and price of the goods returned/adjusted and all particulars are true and correct.
        </div>
      </td>
      <td style="width: 45%; text-align: right; vertical-align: bottom;">
        <div style="font-size: 10.5px; margin-bottom: 45px;">For <b>{{ doc.company }}</b></div>
        <div style="border-top: 1px solid #111827; display: inline-block; min-width: 170px; text-align: center; padding-top: 3px; font-weight: bold; font-size: 10px;">
          Authorized Signatory
        </div>
      </td>
    </tr>
  </table>
</div>
<div style="width: 100%; text-align: center; font-style: italic; font-weight: bold; font-size: 11px; margin-top: 20px; border-top: 1px solid #777; padding-top: 5px;">
    This is computer generated document and does not require a signature.
</div>

