    margin-top:0px;
    margin-bottom:0px;
}
div[data-fieldname="posting_date"] > div:nth-child(1){
    width:50% !important;
    line-height:1.6;
}
div[data-fieldname="posting_date"] > div:nth-child(2){
    width:50% !important;
    line-height:1.6;
}


